mapper.select:
select m.permission_code,

    #{readWrite} as access_level
    rm.access_level

from sys_menus m

    inner join sys_tenant_menu_rel tm on tm.menu_id = m.id
        and tm.tenant_id = #{tenantId} and tm.del_flag = 0 and tm.data_status = #{enabled}

        inner join sys_role_menu_rel rm on rm.menu_id = m.id
            and rm.tenant_id = tm.tenant_id and rm.del_flag = 0 and rm.data_status = #{enabled}
        inner join sys_role r on r.id = rm.role_id
            and r.tenant_id = rm.tenant_id and r.del_flag = 0 and r.data_status = #{enabled}
        inner join sys_user_role_rel ur on ur.role_id = r.id
            and ur.tenant_id = r.tenant_id and ur.del_flag = 0 and ur.data_status = #{enabled}
            and ur.user_id = #{userId}


where m.del_flag = 0 and m.data_status = #{enabled}
    and m.permission_code is not null and m.menu_type != #{directory}

    and rm.access_level in (#{readOnly}, #{readWrite})
